html:
{%- import "erpnext/templates/print_formats/report_print_macros.html" as rp -%}
{%- set show_company = no_letterhead if no_letterhead is defined else not letter_head -%}
{%- set rows = [] -%}
{%- for row in data if row is mapping and row.voucher_no and not row.is_total_row -%}
	{%- set ignore = rows.append(row) -%}
{%- endfor -%}
{{ rp.styles() }}
<div class="rpf">
	{%- if show_company %}{{ rp.company_header(filters.company) }}{% endif %}
	{%- if filters.include_payments %}
	{%- set entries = data | select("mapping") | rejectattr("is_total_row") | list %}
	{%- set opening = entries[0] if entries and not entries[0].voucher_no else None %}
	{%- set moves = entries | selectattr("voucher_no") | list %}
	{{ rp.head(_("Sales Register"), rp.period(filters.from_date, filters.to_date), ((moves[0].customer_name if moves else None) or filters.customer) | e) }}
	<table class="rpf-grid">
		<colgroup><col style="width: 80px"><col><col style="width: 140px"><col style="width: 112px"><col style="width: 112px"><col style="width: 128px"></colgroup>
		<thead>
			<tr>
				<th>{{ _("Date") }}</th>
				<th>{{ _("Voucher Type") }}</th>
				<th>{{ _("Voucher No.") }}</th>
				<th class="num">{{ _("Debit") }}</th>
				<th class="num">{{ _("Credit") }}</th>
				<th class="num">{{ _("Balance") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- if opening and (opening.debit or opening.credit or opening.balance) %}
			<tr>
				<td class="nowrap">{{ rp.date(filters.from_date) }}</td>
				<td>{{ _("Opening Balance") }}</td>
				<td></td>
				<td class="num">{{ rp.money(opening.debit) }}</td>
				<td class="num">{{ rp.money(opening.credit) }}</td>
				<td class="num">{{ rp.drcr(opening.balance) }}</td>
			</tr>
			{%- endif %}
			{%- set last = namespace(date=None) %}
			{%- for row in moves %}
			<tr>
				<td class="nowrap">{% if row.posting_date != last.date %}{{ rp.date(row.posting_date) }}{% endif %}</td>
				<td>{% if row.voucher_type == "Payment Entry" %}{{ _("Receipt") if row.credit else _("Payment") }}{% elif row.voucher_type == "Sales Invoice" %}{{ _("Credit Note") if row.debit < 0 else _("Sales") }}{% else %}{{ rp.vch_type(row) }}{% endif %}</td>
				<td class="nowrap muted">{{ row.voucher_no | e }}</td>
				<td class="num">{{ rp.money(row.debit) }}</td>
				<td class="num">{{ rp.money(row.credit) }}</td>
				<td class="num">{{ rp.drcr(row.balance) }}</td>
			</tr>
			{%- set last.date = row.posting_date %}
			{%- else %}
			<tr><td colspan="6" class="rpf-empty">{{ _("No transactions in this period") }}</td></tr>
			{%- endfor %}
			{%- if moves %}
			<tr class="total">
				<td></td>
				<td colspan="2">{{ _("Total") }}</td>
				<td class="num"><span class="double">{{ rp.money(moves | map(attribute="debit") | map("float") | sum) }}</span></td>
				<td class="num"><span class="double">{{ rp.money(moves | map(attribute="credit") | map("float") | sum) }}</span></td>
				<td class="num">{{ rp.drcr(moves[-1].balance) }}</td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
	{%- else %}
	{{ rp.head(_("Sales Register"), rp.period(filters.from_date, filters.to_date)) }}
	<table class="rpf-grid">
		<colgroup><col style="width: 80px"><col style="width: 140px"><col><col style="width: 112px"><col style="width: 104px"><col style="width: 112px"></colgroup>
		<thead>
			<tr>
				<th>{{ _("Date") }}</th>
				<th>{{ _("Invoice No.") }}</th>
				<th>{{ _("Customer") }}</th>
				<th class="num">{{ _("Taxable Value") }}</th>
				<th class="num">{{ _("Tax") }}</th>
				<th class="num">{{ _("Invoice Total") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- for row in rows %}
			<tr>
				<td class="nowrap">{{ rp.date(row.posting_date) }}</td>
				<td class="nowrap">{{ row.voucher_no | e }}</td>
				<td>
					{{ (row.customer_name or row.customer) | e }}
					{%- if row.tax_id %}<div class="note">{{ _("GSTIN") }} {{ row.tax_id | e }}</div>{% endif %}
				</td>
				<td class="num">{{ rp.money(row.net_total) }}</td>
				<td class="num">{{ rp.money(row.tax_total) }}</td>
				<td class="num">{{ rp.money(row.grand_total) }}</td>
			</tr>
			{%- else %}
			<tr><td colspan="6" class="rpf-empty">{{ _("No invoices in this period") }}</td></tr>
			{%- endfor %}
			{%- if rows %}
			<tr class="total">
				<td colspan="3">{{ _("Total") }} · {{ (_("{0} invoice") if rows | length == 1 else _("{0} invoices")).format(rows | length) }}</td>
				<td class="num"><span class="double">{{ rp.money(rows | map(attribute="net_total") | map("float") | sum) }}</span></td>
				<td class="num"><span class="double">{{ rp.money(rows | map(attribute="tax_total") | map("float") | sum) }}</span></td>
				<td class="num"><span class="double">{{ rp.money(rows | map(attribute="grand_total") | map("float") | sum) }}</span></td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
	{%- endif %}
	{{ rp.footnote() }}
</div>
